import 'dart:io';

import 'package:meta/meta.dart';
import 'package:path/path.dart';
import 'package:pubspec_parse/pubspec_parse.dart';

import '../../gen/package_metadata.dart' as package;
import 'hook_scripts.dart';

@internal
class ForeignHooksException(final List<File> hooks) implements Exception {
  String get message =>
      'The following git hooks were not generated by setup_hooks: '
      '${hooks.map((hook) => hook.path).join(', ')}. '
      'Rerun with --force to replace them.';

  @override
  String toString() => 'ForeignHooksException: $message';
}

@internal
class HookInstaller(
  final Directory workingDirectory, {
  final Map<String, String>? environment,
}) {
  static const _missingFlutterWarning =
      'The pre-push hook checks the flutter compatibility, but flutter was '
      'not found in the PATH. Install flutter or rerun with '
      '--no-flutter-compat.';

  Future<List<File>> install({
    required bool flutterCompat,
    required bool force,
  }) async {
    final hooksDir = Directory(
      normalize(
        absolute(
          workingDirectory.path,
          await _git(['rev-parse', '--git-path', 'hooks']),
        ),
      ),
    );

    final hooks = {
      File(join(hooksDir.path, 'pre-commit')): HookScripts.preCommit,
      File(join(hooksDir.path, 'pre-push')): HookScripts.prePush(
        flutterCompat: flutterCompat,
      ),
    };

    if (!force) {
      final foreignHooks = [
        for (final hook in hooks.keys)
          if (hook.existsSync() &&
              !(await hook.readAsString()).contains(HookScripts.marker))
            hook,
      ];
      if (foreignHooks.isNotEmpty) {
        throw ForeignHooksException(foreignHooks);
      }
    }

    await hooksDir.create(recursive: true);
    for (final MapEntry(key: hook, value: script) in hooks.entries) {
      await hook.writeAsString(script);
      if (!Platform.isWindows) {
        final result = await Process.run('chmod', ['755', hook.path]);
        if (result.exitCode != 0) {
          throw Exception(
            'Failed to make ${hook.path} executable: ${result.stderr}',
          );
        }
      }
    }

    return hooks.keys.toList();
  }

  Future<List<String>> warnings({required bool flutterCompat}) async {
    if (!flutterCompat) {
      return const [];
    }

    final topLevel = await _git(['rev-parse', '--show-toplevel']);
    return [
      if (!await _dependsOnDartTestTools(topLevel))
        _missingDependencyWarning(topLevel),
      if (!_hasFlutter()) _missingFlutterWarning,
    ];
  }

  Future<bool> _dependsOnDartTestTools(String topLevel) async {
    final pubspecFile = File(join(topLevel, 'pubspec.yaml'));
    if (!pubspecFile.existsSync()) {
      return false;
    }

    final pubspec = Pubspec.parse(
      await pubspecFile.readAsString(),
      sourceUrl: pubspecFile.uri,
      lenient: true,
    );
    return pubspec.dependencies.containsKey(package.package) ||
        pubspec.devDependencies.containsKey(package.package);
  }

  String _missingDependencyWarning(String topLevel) =>
      'The pre-push hook runs "dart run ${package.package}:flutter_compat", '
      'but the pubspec.yaml in $topLevel does not depend on '
      '${package.package}. Add it as dev dependency or rerun with '
      '--no-flutter-compat.';

  bool _hasFlutter() {
    final path = _pathVariable();
    if (path == null) {
      return false;
    }

    final flutter = Platform.isWindows ? 'flutter.bat' : 'flutter';
    return path
        .split(Platform.isWindows ? ';' : ':')
        .where((dir) => dir.isNotEmpty)
        .any((dir) => File(join(dir, flutter)).existsSync());
  }

  String? _pathVariable() {
    for (final env in [?environment, Platform.environment]) {
      for (final MapEntry(:key, :value) in env.entries) {
        if (key.toUpperCase() == 'PATH') {
          return value;
        }
      }
    }
    return null;
  }

  Future<String> _git(List<String> arguments) async {
    final result = await Process.run(
      'git',
      arguments,
      workingDirectory: workingDirectory.path,
      environment: environment,
    );
    if (result.exitCode != 0) {
      throw Exception(
        'git ${arguments.join(' ')} failed with exit code ${result.exitCode}: '
        '${(result.stderr as String).trim()}',
      );
    }
    return (result.stdout as String).trim();
  }
}
